namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Commands;

/// <summary>
///     Command to record the attention of an authorized user for a pending alert.
/// </summary>
/// <param name="AlertId">The alert to attend.</param>
/// <param name="OperationId">The identifier generated by the client, reused on every retry.</param>
/// <param name="Finding">What the user found.</param>
/// <param name="Action">What the user did, if anything.</param>
/// <param name="ExpectedVersion">The alert version last read by the client.</param>
public sealed record AcknowledgeAlertCommand(Guid AlertId, Guid OperationId, string Finding, string? Action, int ExpectedVersion);
